parameters.jsCode:
const despesas = $input.first().json.despesas;
const phone = $('WF-DPV.04 - TRIGGER | Gerar Relatorio').first().json.phone;
const funcionarioNome = despesas[0]?.funcionario_nome || phone;

const totalGeral = despesas.reduce((acc, d) => acc + parseFloat(d.valor_total), 0);
const datasEmissao = despesas.map(d => d.data_emissao).filter(Boolean).sort();
const dataInicio = datasEmissao.length ? new Date(datasEmissao[0]).toLocaleDateString('pt-BR') : 'N/A';
const dataFim = datasEmissao.length ? new Date(datasEmissao[datasEmissao.length - 1]).toLocaleDateString('pt-BR') : 'N/A';

const catLabels = { alimentacao: 'Alimentacao', combustivel: 'Combustivel', hospedagem: 'Hospedagem', transporte: 'Transporte', pedagio: 'Pedagio', outros: 'Outros' };
const pagadorLabels = { empresa: 'Empresa', particular: 'Colaborador', cliente: 'Cliente' };
const formaLabels = { cartao: 'Cartao', dinheiro: 'Dinheiro', pix: 'Pix' };

function formatObservacao(obs) {
  if (!obs || obs === 'NAO') return '-';
  if (obs === 'DESCONTO BEBIDA') return 'Desconto bebida';
  if (obs.startsWith('DIVIDIR3')) {
    const partes = obs.replace('DIVIDIR3', '').trim();
    return partes ? 'Divisao ' + partes.replace(/\//g, ' / ') : 'Divisao 3 vias';
  }
  if (obs.startsWith('DIVIDIR')) {
    const partes = obs.replace('DIVIDIR', '').trim();
    return partes ? 'Divisao ' + partes.replace('/', '% / ') + '%' : 'Divisao';
  }
  return obs;
}

function splitValores(d) {
  const valorTotal = parseFloat(d.valor_total) || 0;
  if (d.tipo_despesa === 'cliente') {
    return { empresa: 0, funcionario: 0, cliente: valorTotal };
  }
  const ve = (d.valor_empresa !== null && d.valor_empresa !== undefined) ? parseFloat(d.valor_empresa) : null;
  const vf = (d.valor_funcionario !== null && d.valor_funcionario !== undefined) ? parseFloat(d.valor_funcionario) : null;
  const vc = (d.valor_cliente !== null && d.valor_cliente !== undefined) ? parseFloat(d.valor_cliente) : null;
  if (ve !== null || vf !== null || vc !== null) {
    return { empresa: ve || 0, funcionario: vf || 0, cliente: vc || 0 };
  }
  if (d.tipo_pagador === 'particular') {
    return { empresa: 0, funcionario: valorTotal, cliente: 0 };
  }
  return { empresa: valorTotal, funcionario: 0, cliente: 0 };
}

const categorias = despesas.reduce((acc, d) => {
  const cat = d.categoria || 'outros';
  acc[cat] = (acc[cat] || 0) + parseFloat(d.valor_total);
  return acc;
}, {});

const totais = despesas.reduce((acc, d) => {
  const v = splitValores(d);
  acc.empresa += v.empresa;
  acc.funcionario += v.funcionario;
  acc.cliente += v.cliente;
  return acc;
}, { empresa: 0, funcionario: 0, cliente: 0 });

const linhasDespesas = despesas.map(d => {
  const v = splitValores(d);
  return `
  <tr>
    <td>${d.ordem_nf ?? '-'}</td>
    <td>${new Date(d.data_emissao).toLocaleDateString('pt-BR')}</td>
    <td>${d.estabelecimento || ''}</td>
    <td>${catLabels[d.categoria] || d.categoria}</td>
    <td>${pagadorLabels[d.tipo_pagador] || d.tipo_pagador || '-'}</td>
    <td>${formaLabels[d.forma_pagamento] || d.forma_pagamento || '-'}</td>
    <td>${formatObservacao(d.observacao)}</td>
    <td style="text-align:right">${v.empresa ? 'R$ ' + v.empresa.toFixed(2) : '-'}</td>
    <td style="text-align:right">${v.funcionario ? 'R$ ' + v.funcionario.toFixed(2) : '-'}</td>
    <td style="text-align:right">${v.cliente ? 'R$ ' + v.cliente.toFixed(2) : '-'}</td>
  </tr>
`;
}).join('');

const linhasCategorias = Object.entries(categorias).sort((a,b)=>b[1]-a[1]).map(([cat, val]) => `
  <tr>
    <td><strong>${catLabels[cat] || cat}</strong></td>
    <td style="text-align:right"><strong>R$ ${val.toFixed(2)}</strong></td>
  </tr>
`).join('');

const despesasCliente = despesas.filter(d => d.tipo_despesa === 'cliente');
const totalCliente = despesasCliente.reduce((acc, d) => acc + parseFloat(d.valor_total), 0);
const linhasCliente = despesasCliente.map(d => `
  <tr>
    <td>${new Date(d.data_emissao).toLocaleDateString('pt-BR')}</td>
    <td>${d.estabelecimento || ''}</td>
    <td>${catLabels[d.categoria] || d.categoria}</td>
    <td style="text-align:right">R$ ${parseFloat(d.valor_total).toFixed(2)}</td>
  </tr>
`).join('');

const secaoCliente = despesasCliente.length ? `
<h2>Despesas a Cobrar do Cliente</h2>
<table>
  <tr><th>Data</th><th>Estabelecimento</th><th>Categoria</th><th style="text-align:right">Valor</th></tr>
  ${linhasCliente}
  <tr class="total-row"><td colspan="3">TOTAL A COBRAR</td><td style="text-align:right">R$ ${totalCliente.toFixed(2)}</td></tr>
</table>
` : '';

const comprovantes = despesas.filter(d => d.imagem_nf_base64);
const linhasComprovantes = comprovantes.map(d => `
  <div style="margin-bottom:20px;">
    <img src="data:${d.imagem_nf_mimetype};base64,${d.imagem_nf_base64}" style="max-width:400px; display:block;">
    <p style="font-size:12px; color:#666; margin-top:4px;">NF #${d.ordem_nf ?? '-'} - ${d.estabelecimento || ''} - ${new Date(d.data_emissao).toLocaleDateString('pt-BR')}</p>
  </div>
`).join('');

const secaoComprovantes = comprovantes.length ? `
<h2>Comprovantes</h2>
${linhasComprovantes}
` : '';

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; margin: 40px; color: #333; }
  h1 { color: #1a5276; border-bottom: 2px solid #1a5276; padding-bottom: 10px; }
  h2 { color: #2874a6; margin-top: 30px; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th { background: #1a5276; color: white; padding: 8px; text-align: left; }
  td { padding: 8px; border-bottom: 1px solid #ddd; }
  tr:nth-child(even) { background: #f2f2f2; }
  .total-row { background: #d5e8d4 !important; font-weight: bold; font-size: 16px; }
  .header-info { display: flex; gap: 40px; margin: 20px 0; background: #eaf4ff; padding: 15px; border-radius: 8px; }
  .header-info div { flex: 1; }
  .label { font-size: 12px; color: #666; }
  .value { font-size: 16px; font-weight: bold; }
</style>
</head>
<body>
<h1>Relatorio de Despesas de Viagem</h1>
<div class="header-info">
  <div><div class="label">Funcionario</div><div class="value">${funcionarioNome}</div></div>
  <div><div class="label">Periodo</div><div class="value">${dataInicio} a ${dataFim}</div></div>
  <div><div class="label">Total Geral</div><div class="value">R$ ${totalGeral.toFixed(2)}</div></div>
  <div><div class="label">Total Notas</div><div class="value">${despesas.length}</div></div>
</div>

<h2>Resumo por Categoria</h2>
<table>
  <tr><th>Categoria</th><th style="text-align:right">Total</th></tr>
  ${linhasCategorias}
  <tr class="total-row"><td>TOTAL GERAL</td><td style="text-align:right">R$ ${totalGeral.toFixed(2)}</td></tr>
</table>

<h2>Detalhamento das Despesas</h2>
<table>
  <tr>
    <th>NF</th><th>Data</th><th>Estabelecimento</th><th>Categoria</th><th>Quem Pagou</th><th>Como Pagou</th>
    <th>Desconto/Divisao</th><th style="text-align:right">Empresa</th><th style="text-align:right">Funcionario</th><th style="text-align:right">Cliente</th>
  </tr>
  ${linhasDespesas}
  <tr class="total-row">
    <td colspan="7">TOTAL</td>
    <td style="text-align:right">R$ ${totais.empresa.toFixed(2)}</td>
    <td style="text-align:right">R$ ${totais.funcionario.toFixed(2)}</td>
    <td style="text-align:right">R$ ${totais.cliente.toFixed(2)}</td>
  </tr>
</table>
${secaoComprovantes}
${secaoCliente}

<p style="margin-top:40px; font-size:12px; color:#888;">Relatorio gerado em ${new Date().toLocaleString('pt-BR')} | Sistema dep-viagem</p>
</body>
</html>`;

return [{ json: { html, phone, funcionarioNome, totalGeral, dataInicio, dataFim, qtdNotas: despesas.length } }];

